/// <summary>
/// The TFMDocumentNode is a class matching a XML tag in an xml document.
/// </summary>
class TFMDocumentNode
{

    Map                                 children;
    int64                               parentID;
    Map                                 attributes;
    str                                 name;
    str                                 value;
    TFMDocumentNodes                    cData;
    XML                                 cDataXML;
    Map                                 childNameCount;
    int64                               nodeID;
    TFMDocumentNodes                    owner;

}

Method.Source:
protected void new(int64 _nodeID, TFMDocumentNode _parent, TFMDocumentNodes _nodes)
{
    parentID        = _parent == null ? 0 : _parent.getnodeID();        
    children        = new Map(Types::String,Types::int64);
    attributes      = new Map(Types::String,Types::String);
    childNameCount  = new Map(Types::String,types::Integer);
    nodeID          = _nodeID;
    owner           = _nodes;
    cData           = null;
}

public static TFMDocumentNode Construct(int64 _nodeID, TFMDocumentNode _parent, TFMDocumentNodes _nodes)
{
    return new TFMDocumentNode(_nodeID,  _parent, _nodes);
}

/// <summary>
/// Get the owner or parent.
/// </summary>
/// <returns>The TFMDocumentNodes instance, that this class belongs to.</returns>
public TFMDocumentNodes owner()
{
    return owner;
}

/// <summary>
/// Method used to add Attributes to the node.
/// </summary>
/// <param name = "_key">Attribute key.</param>
/// <param name = "_value">Attribute value.</param>
public void addAttribute(str _key, str _value)
{
    attributes.insert(_key,_value);
}

/// <summary>
/// Method used to add children to the current node.
/// </summary>
/// <param name = "_child">The child node that should be added.</param>
public void addChild(TFMDocumentNode _child)
{
    children.insert(strRFix(int2str(children.elements()+1),4,'0') ,_child.getNodeID());
}

private void addToMap(Map _map, str _key, int _value)
{
    int content = 0;

    if (_map.exists(_key))
    {
        content = _map.lookup(_key);
        _map.remove(_key);
    }

    content += _value;
    _map.insert(_key, content);
}

public Map parmAttributes(Map _attributes = attributes)
{
    attributes = _attributes;
    return attributes;
}

public Str parmName(Str _name = name)
{
    name = _name;
    return name;
}

public int64 parmParentID(int64 _parentID = parentID)
{
    parentID = _parentID;
    return parentID;
}

public XML getCDataAsXML()
{
    return cDataXML ?  cDataXML : (cData == null ? '' : cData.makeXml().xml());
}

public Str parmValue(Str _value = value)
{

    value = _value;

    return value;
}
